<?php
require __DIR__.'/_init.php';require __DIR__.'/_layout.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$co=company();$logo=$co['logo_path']??null;if(isset($_POST['remove_logo'])){delete_local_file($logo);$logo=null;}if(!empty($_FILES['logo']['name'])){$new=upload_image($_FILES['logo'],'logo');delete_local_file($logo);$logo=$new;}
$s=db()->prepare('UPDATE company SET name=?,slogan=?,description=?,phone=?,whatsapp=?,email=?,address=?,website=?,logo_path=? WHERE id=1');$s->execute([trim($_POST['name']??''),trim($_POST['slogan']??''),trim($_POST['description']??''),trim($_POST['phone']??''),trim($_POST['whatsapp']??''),trim($_POST['email']??''),trim($_POST['address']??''),trim($_POST['website']??''),$logo]);flash('Dados da empresa atualizados.');}catch(Throwable $e){flash($e->getMessage(),'error');}header('Location: company.php');exit;}
$co=company();admin_header('Dados da empresa','company');?>
<div class="panel"><h2>Identidade e contato</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><label>Nome da empresa<input name="name" required value="<?=e($co['name']??'')?>"></label><label>Slogan<input name="slogan" value="<?=e($co['slogan']??'')?>"></label><label class="wide">Descrição da empresa<textarea name="description"><?=e($co['description']??'')?></textarea></label><label>Telefone<input name="phone" value="<?=e($co['phone']??'')?>"></label><label>WhatsApp (com DDD)<input name="whatsapp" value="<?=e($co['whatsapp']??'')?>"></label><label>E-mail<input type="email" name="email" value="<?=e($co['email']??'')?>"></label><label>Site<input name="website" value="<?=e($co['website']??'')?>"></label><label class="wide">Endereço<input name="address" value="<?=e($co['address']??'')?>"></label><label class="wide">Logo da empresa<input type="file" name="logo" accept="image/jpeg,image/png,image/webp,image/gif"></label></div><?php if(!empty($co['logo_path'])):?><img class="logo-preview" src="../<?=e($co['logo_path'])?>" alt="Logo atual"><label style="margin-top:12px"><input type="checkbox" name="remove_logo" value="1" style="display:inline;width:auto"> Remover logo atual</label><?php endif;?><div class="actions"><button class="btn primary">Salvar dados</button></div></form></div>
